::CORBA::Boolean POA_AMI_BHandler::_is_a (char const *value)
{
  return
    (
      std::strcmp (value, "IDL:omg.org/Messaging/ReplyHandler:1.0") == 0 ||
      std::strcmp (value, "IDL:AMI_BHandler:1.0") == 0 ||
      std::strcmp (value, "IDL:omg.org/CORBA/Object:1.0") == 0
    );
}

char const *POA_AMI_BHandler::_interface_repository_id () const
{
  return "IDL:AMI_BHandler:1.0";
}

void POA_AMI_BHandler::_dispatch (
  TAO_ServerRequest & req,
  TAO::Portable_Server::Servant_Upcall* servant_upcall)
{
  this->synchronous_upcall_dispatch (req, servant_upcall, this);
}

AMI_BHandler *
POA_AMI_BHandler::_this ()
{
  TAO_Stub_Auto_Ptr stub (this->_create_stub ());
  bool const _tao_opt_colloc = stub->servant_orb_var ()->orb_core ()->optimize_collocation_objects ();
  ::CORBA::Object_var obj = new (std::nothrow) ::CORBA::Object (stub.get (), _tao_opt_colloc, this);
  if (obj.ptr ())
    {
      (void) stub.release ();
      return TAO::Narrow_Utils<::AMI_BHandler>::unchecked_narrow (obj.in ());
    }
  return {};
}

